stats = dict()
for u in users:
    stats[u] =  {
        "info": 0,
        "error": 0,
        "tickets": []
    }


n = int(input().strip())

for _ in range(n):
    line = input().strip()
    if not line:
        continue

    parts = line.split(",")

    ticket_code, username, log_message = parts

    if username not in stats:
        continue

    if len(ticket_code) < 7:
        continue

    id_str = ticket_code[3:7]

    if len(id_str) != 4:
        continue
    if not id_str.isdigit():
        continue
    if id_str[0] == '0':
        continue


    if log_message.startswith("[INFO]"):
        stats[username]["info"] += 1
    elif log_message.startswith("[ERROR]"):
        stats[username]["error"] += 1
    else:
        continue

    stats[username]["tickets"].append(int(id_str))


for u in users:
    tickets_sorted = sorted(stats[u]["tickets"])
    print(f"{u}: INFO={stats[u]['info']} ERROR={stats[u]['error']} TICKET={tickets_sorted }")
